     , apr01_status_cd      = #{statusCode}
     , apr01_effect_date    = #{req.effectDate}
     , apr01_reg_date       = #{req.regDate}
     , apr01_stamp_id       = #{req.stampId}
     , apr01_receive_nm     = #{req.receiveName}
